/* =========================================================
   page-loader.js — หน้าโหลดทุกหน้า: ปิกาจูสีแดงวิ่ง + ข้อความ "ກຳລັງໂຫລດ"
   วางไว้ใน <head> บนสุด เพื่อให้ขึ้นทันทีก่อนหน้าเว็บวาดเสร็จ
   - CSS + รูปสไปรต์ฝังอยู่ในไฟล์นี้ทั้งหมด (ไม่ต้องรอ page-loader.css / assets โหลด)
     จึงขึ้นพร้อมกับเฟรมแรกของหน้า ไม่มีจังหวะที่เห็นหน้าเว็บก่อนหรือเห็นหน้าโหลดไม่ครบ
   - ปิกาจูวิ่งต่อเนื่องข้ามหน้า (เฟสแอนิเมชั่นอิงเวลาเครื่อง) ตอนกดเปลี่ยนหน้าจึงไม่สะดุด
   ซ่อนเมื่อ: หน้าโหลดเสร็จ + ข้อมูลร้านจาก /api/public/storefront มาแล้ว
   (หรือครบเวลาสูงสุด 8 วินาที กันค้าง) แล้วเฟดออก
   ========================================================= */
(function () {
  var root = document.documentElement;
  var MIN_SHOW_MS = 1150;  // โชว์อย่างน้อยเท่านี้ (มิลลิวินาที) จะได้เห็นปิกาจูวิ่ง — อยากให้ช้า/เร็วกว่านี้แก้เลขตรงนี้
  var MAX_WAIT_MS = 8000;  // รอนานสุด แล้วเปิดหน้าให้เลย
  var EXIT_MS = 320;       // ความยาวเฟดออก (ต้องมากกว่า .25s ในสไตล์ด้านล่าง)
  var RUN_MS = 280;        // ปิกาจูวิ่งครบ 4 เฟรมใช้เวลาเท่านี้ (ต้องตรง pl-run ด้านล่าง)
  var start = Date.now();
  var done = false;
  var reduced = false;
  try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}

  // ---- สไตล์ (ฝังในไฟล์นี้ — ใส่ก่อนสร้าง overlay เสมอ) ----
  var SPRITE = 'data:image/webp;base64,';
  var CSS =
    'html.pl-lock{overflow:hidden}' +
    '#page-loader{position:fixed;top:0;right:0;bottom:0;left:0;z-index:99999;display:flex;align-items:center;justify-content:center;' +
      'background:#0c0c0c;opacity:1;visibility:visible;animation:pl-failsafe 0s linear 10s forwards}' +
    '@keyframes pl-failsafe{to{opacity:0;visibility:hidden;pointer-events:none}}' +
    '#page-loader .pl-stage{display:flex;flex-direction:column;align-items:center;gap:14px}' +
    '#page-loader .pl-pika{width:112px;height:81px;background:url(' + SPRITE + ') 0 0/448px 81px no-repeat;' +
      'image-rendering:pixelated;filter:drop-shadow(0 0 14px rgba(255,0,1,.35));' +
      'animation:pl-run ' + RUN_MS + 'ms steps(4) infinite;will-change:background-position}' +
    '@keyframes pl-run{to{background-position:-448px 0}}' +
    "#page-loader .pl-text{font:600 15px/1.4 'Noto Sans Lao','Lao Sangam MN','Leelawadee UI','Phetsarath OT','Saysettha OT',system-ui,sans-serif;" +
      'color:#6e6e6e;letter-spacing:.2px;text-align:center}' +
    '#page-loader .pl-word{position:relative;display:inline-block}' +
    '#page-loader .pl-dots{position:absolute;left:100%;top:0;white-space:nowrap}' +
    '#page-loader .pl-dots i{font-style:normal}' +
    '#page-loader .pl-dots i:nth-child(2){animation:pl-d2 1.2s linear infinite}' +
    '#page-loader .pl-dots i:nth-child(3){animation:pl-d3 1.2s linear infinite}' +
    '@keyframes pl-d2{0%,32.9%{opacity:0}33%,100%{opacity:1}}' +
    '@keyframes pl-d3{0%,65.9%{opacity:0}66%,100%{opacity:1}}' +
    '#page-loader.pl-hide,#page-loader.pl-exit{opacity:0;visibility:hidden;pointer-events:none;animation:none;' +
      'transition:opacity .25s ease,visibility 0s linear .25s}' +
    '@media (prefers-reduced-motion:reduce){#page-loader .pl-pika,#page-loader .pl-dots i{animation:none}}';
  var st = document.createElement('style');
  st.id = 'page-loader-style';
  st.appendChild(document.createTextNode(CSS));
  (document.head || root).appendChild(st);

  // สร้าง overlay — แชร์ให้ page-transition.js เรียกใช้ตอนกดลิงก์ด้วย (หน้าตาเดียวกันเป๊ะ)
  function build() {
    var el = document.createElement('div');
    el.id = 'page-loader';
    el.setAttribute('role', 'status');
    el.setAttribute('aria-label', 'Loading');
    el.innerHTML =
      '<div class="pl-stage">' +
        '<div class="pl-pika"></div>' +
        '<div class="pl-text"><span class="pl-word">ກຳລັງໂຫລດ<span class="pl-dots"><i>.</i><i>.</i><i>.</i></span></span></div>' +
      '</div>';
    // ให้ปิกาจูวิ่งต่อจังหวะเดิมข้ามหน้า: ใช้เวลาเครื่องเป็นตัวกำหนดเฟส
    el.querySelector('.pl-pika').style.animationDelay = '-' + (Date.now() % RUN_MS) + 'ms';
    return el;
  }
  window.__plBuild = build;

  var el = build();
  root.classList.add('pl-lock');
  root.appendChild(el); // ใส่ที่ <html> ได้เลย ไม่ต้องรอ <body>

  function remove() { if (el.parentNode) el.parentNode.removeChild(el); }

  function finish() {
    if (done) return;
    done = true;
    var wait = Math.max(0, MIN_SHOW_MS - (Date.now() - start));
    setTimeout(function () {
      // รอ 2 เฟรมให้เนื้อหาที่เพิ่งเติมวาดเสร็จก่อนค่อยเฟดออก
      requestAnimationFrame(function () {
        requestAnimationFrame(function () {
          // ปลดล็อกการเลื่อนทันที — หน้าพร้อมใช้งานตั้งแต่เริ่มเปิด ไม่ต้องรอเฟดจบ
          root.classList.remove('pl-lock');
          if (reduced) {
            el.classList.add('pl-hide');
            setTimeout(remove, 400);
          } else {
            el.classList.add('pl-exit');
            setTimeout(remove, EXIT_MS);
            // กันเหนียว: ถ้าแท็บอยู่เบื้องหลังแล้ว timer ช้า ก็ยังเอาออกแน่ๆ
            setTimeout(remove, EXIT_MS + 1500);
          }
        });
      });
    }, wait);
  }

  // กันค้างสูงสุด
  setTimeout(finish, MAX_WAIT_MS);

  var pageLoaded = new Promise(function (res) {
    if (document.readyState === 'complete') res();
    else window.addEventListener('load', res);
  });

  // รอข้อมูลร้าน (ถ้าหน้านั้นใช้) — สำเร็จหรือพลาดก็ถือว่า "เสร็จ" จะได้ไม่ค้าง
  var dataReady = new Promise(function (res) {
    var tries = 0;
    (function poll() {
      if (window.StorefrontData && window.StorefrontData.fetchData) {
        window.StorefrontData.fetchData().then(res, res);
      } else if (++tries > 100) { res(); }      // หน้านี้ไม่ได้ใช้ข้อมูลร้าน
      else setTimeout(poll, 20);
    })();
  });

  Promise.all([pageLoaded, dataReady]).then(function () {
    // เว้นจังหวะให้ script ของแต่ละหน้าเติมข้อมูลลง DOM ก่อน
    setTimeout(finish, 30);
  });

  // กด "ย้อนกลับ" แล้วหน้ากลับมาจาก bfcache -> อย่าให้ overlay ค้าง
  window.addEventListener('pageshow', function (e) {
    if (e.persisted) { remove(); root.classList.remove('pl-lock'); }
  });
})();
